// One item per (unit, lead) that actually has BOTH a miss and a resolvable lead. A unit whose
// leadUserIds is empty (no manager placed inside that unit -- the open architectural gap the
// endpoint itself documents) is skipped here, never escalated to a lead outside it.
const body = $input.first().json.body ?? $input.first().json;
const date = body.date;
const byUnit = Array.isArray(body.byUnit) ? body.byUnit : [];
const out = [];
for (const u of byUnit) {
  if (!u.missedUserIds?.length || !u.leadUserIds?.length) continue;
  for (const leadUserId of u.leadUserIds) {
    out.push({ json: { tenantId: $env.AGENCY_TENANT_ID, recipientId: leadUserId, unitNodeId: u.unitNodeId, count: u.missedUserIds.length, date } });
  }
}
return out;
